def safe_int(value):
    try:
        result = int(value)
    except ValueError:
        print('Conversion failed')
        return None
    else:
        print('Converted successfully')
        return result
    finally:
        print('Done')

safe_int('42')   # Converted successfully / Done -> 42
safe_int('abc')  # Conversion failed / Done -> None

