import time

def call_with_backoff(func, max_retries=5):
    for attempt in range(max_retries):
        response = func()
        if response.status_code != 429:
            return response
        wait = 2 ** attempt  # exponential backoff
        time.sleep(wait)
    raise Exception('Max retries exceeded')

